using System;using Ashfall.Core;using Ashfall.Modules.HealthStates;
public static class DurableCrashWorker {
 sealed class Ports:IAuthorityGate,IHealthWorld,IInteractionQuery {public double Now{get{return 1;}}public bool InMatch{get{return true;}}public bool TeamChangesAllowed{get{return false;}}public RuleResult Validate(CommandContext c){return c.IsAuthority?RuleResult.Accept():RuleResult.Reject("authority");}public bool TryGetPose(string id,out RescuePose pose){pose=new RescuePose();return false;}public bool HasLineOfSight(string a,string b,Float3 x,Float3 y,float range){return false;}}
 public static void Run(string[] args){var ports=new Ports();var store=new FileHealthImageStore(args[0],"durable",0,new string('b',64),1048576);var h=new HealthService("durable",0,0,true,ports,ports,ports,60,5,0);h.EnableDurableImages(store,new string('b',64));h.RegisterConfiguredSpawn(new CommandContext("durable","host","spawn",1,0,true),"p",-1,false,100,0);h.DrainTransitions();store.FaultInjection=delegate(string point){if(point==args[1])Environment.Exit(71);};h.ApplyDamage(new CommandContext("durable","host","hit",2,0,true),"once","p",h.Read("p").Revision,1,0,false);store.Dispose();}
}
